/* ============ 全局 & 变量 ============ */
:root {
  --ink: #2b2420;
  --paper: #f3ecdc;
  --paper-deep: #e8ddc4;
  --red: #a32025;
  --red-deep: #7f1a1e;
  --gold: #b98a2f;
  --sepia: #c9b98f;
  --cream: #faf5e8;

  --serif: "Songti SC", "STSong", "SimSun", "Noto Serif SC", serif;
  --kai: "Kaiti SC", "STKaiti", "KaiTi", "Noto Serif SC", serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--serif);
  background: var(--paper);
  color: var(--ink);
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

.page {
  position: relative;
  max-width: 1200px;
  margin: 0 auto;
  background: var(--paper);
  box-shadow: 0 0 60px rgba(0, 0, 0, 0.12);
  overflow: hidden;
}

/* 阅读进度条 */
.progressbar {
  position: fixed;
  top: 0;
  left: 0;
  height: 4px;
  background: var(--red);
  z-index: 100;
  width: 0;
  transition: width 0.05s linear;
}

/* ============ Hero ============ */
.hero {
  position: relative;
  min-height: 92vh;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  background:
    radial-gradient(1200px 500px at 20% 10%, rgba(185, 138, 47, 0.18), transparent 60%),
    radial-gradient(1000px 600px at 90% 0%, rgba(163, 32, 37, 0.14), transparent 55%),
    linear-gradient(180deg, #f8f1e0 0%, var(--paper) 45%);
  border-bottom: 6px solid var(--red);
}

.hero__grain {
  position: absolute;
  inset: 0;
  background-image: repeating-linear-gradient(
    45deg,
    rgba(0, 0, 0, 0.02) 0px,
    rgba(0, 0, 0, 0.02) 2px,
    transparent 2px,
    transparent 5px
  );
  pointer-events: none;
}

.hero__content {
  position: relative;
  z-index: 2;
  text-align: center;
  padding: 70px 24px 90px;
}

.hero__sub {
  font-family: var(--kai);
  letter-spacing: 0.6em;
  color: var(--gold);
  font-size: 0.95rem;
  margin-bottom: 26px;
  padding-left: 0.6em;
}

.hero__title {
  font-size: clamp(4rem, 13vw, 9rem);
  font-weight: 700;
  color: var(--red-deep);
  letter-spacing: 0.28em;
  line-height: 1.1;
  margin-left: 0.28em;
  text-shadow: 2px 3px 0 rgba(163, 32, 37, 0.12);
  font-family: var(--kai);
}

.hero__subsub {
  margin-top: 20px;
  font-size: 1.05rem;
  letter-spacing: 0.35em;
  color: var(--ink);
  opacity: 0.78;
}

.hero__tags {
  margin-top: 26px;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
}

.hero__tag {
  padding: 4px 16px;
  border: 1px solid rgba(163, 32, 37, 0.4);
  color: var(--red);
  font-size: 0.9rem;
  letter-spacing: 0.2em;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.35);
}

.hero__rule {
  width: 120px;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--sepia), transparent);
  margin: 34px auto 22px;
}

.hero__epitaph {
  font-family: var(--kai);
  font-size: 1.5rem;
  color: var(--ink);
  letter-spacing: 0.1em;
}

.hero__cta {
  display: inline-block;
  margin-top: 34px;
  padding: 12px 34px;
  background: var(--red);
  color: var(--cream);
  text-decoration: none;
  letter-spacing: 0.35em;
  font-size: 1rem;
  border-radius: 2px;
  transition: background 0.25s ease, transform 0.2s ease;
}

.hero__cta:hover {
  background: var(--red-deep);
  transform: translateY(-2px);
}

/* ============ 引言 ============ */
.intro {
  padding: 90px 9%;
  text-align: center;
